-- A34: referência de papel interno para componente; não cria direito econômico, beneficiário financeiro, valor, percentual, cálculo, cobrança, pagamento, repasse ou integração externa.
alter table public.subdivision_economic_rule_components add constraint subdivision_economic_rule_components_tenant_match unique (id,organization_id);
alter table public.subdivision_internal_party_roles add constraint subdivision_internal_party_roles_tenant_match unique (id,organization_id);
create table public.subdivision_economic_rule_component_role_references (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,economic_rule_component_id uuid not null,internal_party_role_link_id uuid not null,created_by uuid not null references public.identity_subjects(user_id) on delete restrict,created_at timestamptz not null default now(),constraint subdivision_economic_rule_component_role_references_component_fk foreign key(economic_rule_component_id,organization_id) references public.subdivision_economic_rule_components(id,organization_id) on delete restrict,constraint subdivision_economic_rule_component_role_references_role_fk foreign key(internal_party_role_link_id,organization_id) references public.subdivision_internal_party_roles(id,organization_id) on delete restrict,constraint subdivision_economic_rule_component_role_references_unique unique(organization_id,economic_rule_component_id,internal_party_role_link_id));
alter table public.subdivision_economic_rule_component_role_references enable row level security;revoke all on table public.subdivision_economic_rule_component_role_references from public,anon,authenticated;
comment on table public.subdivision_economic_rule_component_role_references is 'A34: referência interna de papel para componente de regra; não cria direito econômico, participação, valor, percentual, cálculo, cobrança, pagamento, repasse ou integração externa.';
create or replace function public.subdivision_add_economic_rule_component_role_reference(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_economic_rule_component_id uuid,p_internal_party_role_link_id uuid,p_correlation_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_existing uuid;v_reference_id uuid;begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);select target_id into v_existing from public.admin_audit_events where command_name='subdivision_add_economic_rule_component_role_reference' and correlation_id=p_correlation_id and outcome='allowed' order by occurred_at desc limit 1;if v_existing is not null then return v_existing;end if;if not exists(select 1 from public.subdivision_economic_rule_components c join public.subdivision_economic_rule_sets s on s.id=c.economic_rule_set_id and s.organization_id=c.organization_id join public.subdivision_internal_party_roles r on r.organization_id=s.organization_id and r.development_id=s.development_id where c.id=p_economic_rule_component_id and c.organization_id=p_organization_id and r.id=p_internal_party_role_link_id) then raise exception using errcode='42501',message='SUBDIVISION_ECONOMIC_RULE_COMPONENT_ROLE_CONTEXT_DENIED';end if;insert into public.subdivision_economic_rule_component_role_references(organization_id,economic_rule_component_id,internal_party_role_link_id,created_by)values(p_organization_id,p_economic_rule_component_id,p_internal_party_role_link_id,p_actor_user_id)on conflict(organization_id,economic_rule_component_id,internal_party_role_link_id)do update set created_by=excluded.created_by returning id into v_reference_id;insert into public.admin_audit_events(correlation_id,actor_user_id,organization_id,command_name,outcome,target_type,target_id,payload_redacted)values(p_correlation_id,p_actor_user_id,p_organization_id,'subdivision_add_economic_rule_component_role_reference','allowed','subdivision_economic_rule_component_role_reference',v_reference_id,jsonb_build_object('module',p_module::text,'purpose_code',trim(p_purpose_code),'internal_role_reference_added',true));return v_reference_id;end;$$;
revoke all on function public.subdivision_add_economic_rule_component_role_reference(uuid,uuid,public.operating_module,text,uuid,uuid,uuid) from public,anon,authenticated;grant execute on function public.subdivision_add_economic_rule_component_role_reference(uuid,uuid,public.operating_module,text,uuid,uuid,uuid) to service_role;
create or replace function public.subdivision_list_economic_rule_component_role_references(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(economic_rule_component_role_reference_id uuid,economic_rule_component_id uuid,internal_party_role_link_id uuid,created_at timestamptz) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select id,economic_rule_component_id,internal_party_role_link_id,created_at from public.subdivision_economic_rule_component_role_references where organization_id=p_organization_id order by created_at desc;end;$$;
revoke all on function public.subdivision_list_economic_rule_component_role_references(uuid,uuid,public.operating_module,text) from public,anon,authenticated;grant execute on function public.subdivision_list_economic_rule_component_role_references(uuid,uuid,public.operating_module,text) to service_role;
